use tokio::time::{timeout, Duration};
match timeout(Duration::from_millis(300), client.authorize(&order)).await {
    Ok(Ok(receipt)) => Ok(receipt),          // the call answered in time
    Ok(Err(e))      => Err(e.into()),        // the call failed on its own
    Err(_elapsed)   => Err(ServiceUnavailable::new("payment timed out")),
}
